 2	/**
 3	 * @package API
 4	 * @subpackage Parameters
 5	 */
 6	
 7	declare(strict_types=1);
 8	
 9	namespace Application\API\Parameters\Type;
10	
11	use Application\API\Parameters\APIParameterException;
12	use Application\API\Parameters\BaseAPIParameter;
13	use Application\API\Parameters\Validation\ParamValidationInterface;
14	use AppUtils\ConvertHelper;
15	
16	/**
17	 * API Parameter: List of strings as an array.
18	 *
19	 * - Accepts comma-separated strings or arrays.
20	 * - Trims whitespace from each item.
21	 * - Filters out empty strings after trimming.
22	 * - Null and empty strings resolve to null.
23	 *
24	 * @package API
25	 * @subpackage Parameters
26	 *
27	 * @property string[] $defaultValue
28	 */
29	class StringListParameter extends BaseAPIParameter
30	{
31	    public function getTypeLabel(): string
32	    {
33	        return t('String List');
34	    }
35	
36	    /**
37	     * @return string[]
38	     */
39	    public function getDefaultValue(): array
40	    {
41	        return $this->defaultValue ?? array();
42	    }
43	
44	    /**
45	     * @param array<int|string,mixed>|string|null $default A comma-separated string or an array of strings. Set to `NULL` to reset to an empty array. Other value types are rejected.
46	     * @return $this
47	     * @throws APIParameterException {@see APIParameterException::ERROR_INVALID_PARAM_VALUE}
48	     */
49	    public function setDefaultValue(int|float|bool|string|array|null $default) : self
50	    {
51	        return parent::setDefaultValue($this->filterValues($this->requireValidType($default)));
52	    }
53	
54	    /**
55	     * @param array<int|string,mixed>|string|null $value A comma-separated string or an array of strings. Set to `NULL` to reset to an empty array. Other value types are rejected.
56	     * @return $this
57	     * @throws APIParameterException {@see APIParameterException::ERROR_INVALID_PARAM_VALUE}
58	     */
59	    public function selectValue(float|int|bool|array|string|null $value): self
60	    {
61	        return parent::selectValue($this->filterValues($this->requireValidType($value)));
62	    }
63	
64	    /**
65	     * @param array<int|string,mixed> $values
66	     * @return string[]
67	     */
68	    private function filterValues(array $values) : array
69	    {
70	        $result = array();
71	
72	        foreach($values as $item)
